function escapeXPathString(str) {
    if (str === null || str === undefined) {
        return "''"; // Return an empty string literal for null/undefined input
    }
    const parts = str.split("'");
    if (parts.length === 1) {
        // No single quotes, can use directly
        return `'${str}'`;
    } else {
        // Contains single quotes, need to use concat
        let escaped = "concat(";
        for (let i = 0; i < parts.length; i++) {
            escaped += `'${parts[i]}'`;
            if (i < parts.length - 1) {
                escaped += ", \"'\", "; // Add the single quote literal (represented as a double-quoted single quote)
            }
        }
        escaped += ")";
        return escaped;
    }
